import base64,hashlib,json,sys,zlib
sys.dont_write_bytecode=True
z=base64.b64decode('',validate=True)
d=zlib.decompressobj(16+zlib.MAX_WBITS);r=d.decompress(z,262145)
assert len(r)<=262144 and d.eof and not d.unconsumed_tail and not d.unused_data
p=json.loads(r);assert set(p)=={'source_b64','plan_b64'}
s=base64.b64decode(p['source_b64'],validate=True);b=base64.b64decode(p['plan_b64'],validate=True)
assert len(s)==37830 and hashlib.sha256(s).hexdigest()=='7bb8e477a1b3d034e327ecdffdd5a3d0f6ac2308b7abed3758cb81f205605b4e'
assert len(b)==2690 and hashlib.sha256(b).hexdigest()=='a250a8945f422d2bea2c9c44360a90c50860c47447a9541361e46a493f4f8d21'
sys.argv=['capture_non_native_diag02.py','--source-sha256','7bb8e477a1b3d034e327ecdffdd5a3d0f6ac2308b7abed3758cb81f205605b4e','--plan-sha256','a250a8945f422d2bea2c9c44360a90c50860c47447a9541361e46a493f4f8d21','--execute-readonly-capture-once']
exec(compile(s,'<reviewed-diag02-non-native-capture>','exec'),{'__name__':'__main__','__file__':'<reviewed-diag02-non-native-capture>','__capture_source_original__':s,'__capture_plan_original__':b})
